INSERT INTO `wawancaras` (`id`, `jenis_wawancara`, `instrumen_id`, `sekolah_id`, `tanggal_wawancara`, `nama_narasumber`, `jabatan_narasumber`, `nama_pewawancara`, `status`, `hasil_wawancara`, `catatan`, `created_at`, `updated_at`, `jawaban_1`, `jawaban_2`, `jawaban_3`, `jawaban_4`, `jawaban_5`, `nama_bcks`, `unit_kerja_bcks`, `angkatan_pelatihan_bcks`, `nama_responden`, `unit_kerja_responden`, `status_responden`, `nama_petugas_monev`, `unit_kerja_petugas`, `tanggal_evaluasi`, `jawaban_6`, `jawaban_7`, `jawaban_8`) VALUES
(3, 'BCKS', NULL, 3, '2026-10-27', 'Taufikurrahman, S.Pd.', 'Perwakilan Guru / Tenaga Kependidikan', 'Ki Agus Mar Efendi, S.Pd., M.Pd.', 'Selesai', 'Berfokus pada klarifikasi dari instrumen/studi bagaimana cara memecahkan masalah dalam mengambil suatu keputusan dan mengevaluasi alternatif memecahkan masalah tersebut dan memantau hasil nya secara berkala.', 'to be continued', '2026-10-27 02:37:14', '2026-10-27 02:37:14', 'Berdampak sekali, dan kunci keberhasilan nya disiplin dan menjalin kerjasama dengan seluruh warga di sekolah baik tenaga pendidik dan tenaga kependidikan dalam penguatan keterampilan manajerial, kesadaran transformatif dan pengambilan keputusan berbasis data.', 'Kendala yang dihadapi dalam menerapkan Rancangan Projek ini keterlibatan (stakeholder) yang minim, kurangnya dukungan atau sinergi aktif dari pengawas,rekan sejawat,maupun warga sekolah dan akurasi data dasar dalam memetakan akar masalah secara tepat menggunakan data rill seperti rapor pendidikan atau hasil asesmen siswa yang kurang akurat.\r\ncara mengatasinya dari kendala yang dihadapi dengan berperan aktif beraktif dalam bersosialisasi untuk menyampaikan rancangan projek baik dari pengawas dan tenaga pendidik yang ada di sekolah ini sehingga projek berjalan dengan baik.', 'Perubahan yang dialami setelah mengikuti pelatihan BCKS dalam mengambil keputusan dan mengelola konflik di sekolah adalah mengidentifikasi akar masalah atau situasi yang membutuhkan tindakan dalam mengumpulkan infomasi untuk mempelajari fakta-fakta yang relevan,setelah itu mengevaluasi alternatif memecahkan masalah tersebut dan memantau hasil nya secara berkala.', 'Dukungan kepala sekolah, rekan guru dan pengawas sekolah sejauh ini sudah sangat mendukung sekali dalam mengimplementasikan ide-ide baru untuk kemajuan sekolah.', 'Untuk memastikan program inovasi yang dimulai tetap berjalan secara berkelanjutan diperlukan pendekatan terstuktur yang berfokus pada sistem dan budaya kerja dengan integrasi proses kerja, standardisasi prosedur (SOP) dan alokasi anggaran khusus sehingga meskipun terjadi pergantian kepemimpina  atau personil maka program yang telah dimulai akan tetap berjalan dengan baik.', 'Baiq Ulfahani', 'SDN 2 Praya', '1', 'Taufikurrahman, S.Pd.', 'SDN 2 Praya', 'Perwakilan Guru / Tenaga Kependidikan', 'Ki Agus Mar Efendi, S.Pd., M.Pd.', 'BGTK NTB', '2026-10-27', NULL, NULL, NULL),
(4, 'BCKS', NULL, 3, '2026-10-27', 'Baiq Ulfahani', 'BCKS', 'Ki Agus Mar Efendi, S.Pd., M.Pd.', 'Selesai', NULL, NULL, '2026-10-28 01:45:43', '2026-10-28 01:45:43', 'Ya Implementasi RPTKS (Rancangan Projek Integratif dan Transformatif Kepala Sekolah) sangat berdampak positif terhadap ekosistem sekolah. terjadi peningkatan efisiensi dalam manajemen sekolah. Iklim kerja yang kolaboratif, serta peningkatan kompetensi guru dalam merancang pembelajaran yang lebih berorientasi pada murid.\r\nKunci keberhasilannya  adalah komunikasi yang efektif, menyampaikan visi dan misi dan tujuan proyek secara transparan agar semua pihak memahami perannya. Komitmen bersama karena adanya kesadaran kolektif untuk keluar dari zona nyaman demi kemajuan kualitas belajar murid.', 'Kendala yang dihadapi adalah Sistem yaitu penyesuaian dengan regulasi atau platform digital baru yang membutuhkan waktu untuk adaptasi operasional.  \r\nAnggaran, keterbatasan dana atau ketidak sesuaian alokasi RKAS dengan kebutuhan mendesak saat eksekusi projek di lapangan.', 'Setelah saya mengikuti pelatihan BCKS, saya merasakan perubahan yang sangat signifikan ke arah yang lebih objektif dan terukur. Pengelolaan Konflik, saya berubah dari bersifat reaktif menjadi persuasif dan kolaboratif, mengutamakan komunikasi asertif untuk mencapai solusi win win solution demi menjaga kondusivitas lingkungan belajar.', 'Dukungan ekosistem sekolah sangat besar dan menjadi faktor kunci keberhasilan dalam mengeksekusi ide-ide baru.', 'Untuk memastikan program inovasi tetap berjalan berkelanjutan meskipun terjadi pergantian kepemimpinan atau personil, strategi yang saya terapkan adalah melegalkan inovasi tersebut ke dalam dokumen resmi sekolah, seperti masuk ke dalam KSP ( Kurikulum satuan Pendidikan ) atau RKAS (Rencana Kegiatan dan Anggaran Sekolah ) agar menjadi program kerja formal institusi bukan program individu. Kaderisasi dan Distribusi Peran melalui membentuk Tim Kerja terstruktur dan melakukan transfer pengetahuan secara berkala. Inovasi tidak boleh tertumpu pada satu figur melainkan di bangun atas dasar kepemimpinan kolektif.', 'Baiq Ulfahani', 'SDN 2 Praya', '1', 'Baiq Ulfahani', 'SDN 2 Praya', 'BCKS', 'Ki Agus Mar Efendi, S.Pd., M.Pd.', 'BGTK NTB', '2026-10-27', NULL, NULL, NULL),
(5, 'TENDIK', NULL, 6, '2026-10-27', 'Siti Aisah,S.Pd.', 'Rekan Sejawat/Guru', 'Eliana Widyastuti,S.E.', 'Selesai', '{\"instansi_petugas\":\"BGTK Provinsi NTB\",\"lokasi_monev\":\"SDN 3 Nyerot\",\"tanggal_pelaksanaan\":\"2026-10-27\",\"jabatan_responden\":\"Rekan Sejawat\\/Guru\",\"satuan_pendidikan\":\"SDN 3 Ngerot\",\"masa_kerja\":\"22\",\"nama_pelatihan\":\"Tim Monitoring dan Evaluasi Program Prioritas Kepemimpinan sekolah, Implementasi 7 Jurus BK Hebat dan Tes Kompetensi Akademik\"}', NULL, '2026-10-28 02:00:15', '2026-10-28 02:00:15', 'Yang bermanfaat dan berkesan adalah peserta membawa solusi untuk masalah yang sedang di hapadi dan membimbing peserta dalam kegiatan yang diikuti peserta merasa dihargai.', 'Mampu menyamapikan ide, jujur dan tetap mengormati rekan kerja dan lebih terbuka terhadap perbedaan cara kerja dalam tim melatih diri agar tetap menjaga pola pikir bertumbuh dan motivasi dalam menghadapi beban kerja.', 'Penggunaan sistem aplikasi baru, sebelumnya pembuatan laporan secara manual selama berjam-jam setelahpelatihan saya mengoptimalkan sistem baru tersebut.', 'Pelatihan mengerjakan teknologi atau sistem tertentu, namun inftrastruktur pendukung di tempat kerja belum memadai, diperlukan waktu khusus untuk fokus mengimplementasikan hasil pelatihan.', 'Terbentuknya komunitas belajar untuk operator dan guru untuk saling berbagi, aplikasi , modul ajar dan berdiskusi mengenai kendala pembelajaran.', NULL, NULL, NULL, 'Siti Aisah,S.Pd.', 'SDN 3 Ngerot', 'Rekan Sejawat/Guru', 'Eliana Widyastuti,S.E.', 'BGTK Provinsi NTB', '2026-10-27', NULL, NULL, NULL),
(6, 'TENDIK', NULL, 4, '2026-10-27', 'H. Mawardi', 'Kepala Sekolah', 'Eliana Widyastuti,S.E.', 'Selesai', '{\"instansi_petugas\":\"BGTK Provinsi NTB\",\"lokasi_monev\":\"SDN 3 Nyerot\",\"tanggal_pelaksanaan\":\"2026-10-27\",\"jabatan_responden\":\"Kepala Sekolah\",\"satuan_pendidikan\":\"SDN 3 Nyerot\",\"masa_kerja\":\"26\",\"nama_pelatihan\":\"Tim Monitoring dan Evaluasi Program Prioritas Kepemimpinan sekolah, Implementasi 7 Jurus BK Hebat dan Tes Kompetensi Akademik\"}', NULL, '2026-10-28 02:26:34', '2026-10-28 02:26:34', 'Materi yang bersifat praktis memberikan dampak instan, ketika peserta pulang membawa solusi untuk masalah yang sedang dihadapi disekolah,nilai dari pelatihan menjadi membekas dalam jangka panjang, fasilitasi yang mampu memicudiskusi secara mendalam, menghargai pendapat, dan membimbing peserta dalam kegiatan yang diikuti.', 'lebih berfokus pada usaha,konsistensi dan pembelajaran yang berkelanjutan daripada sekedar hasil akhir yang instan. Mampu menyampaikan ide, batasan,jujur, dan tetap menghormati rekan kerja. melatih diri agar tetap terjaga pola pikir bertumbuhdan motivasi internal ketika menghadapi beban kerja yang sangat padat secara bertuut-turut.', 'Penggunaan sistem atau aplikasi baru, dan pada saat sebelumnya pembuatan laporan dilakukan secara manual menggunakan spreed sheet terpisah selama berjam-jam setelah pelatihan saya mengoptimalkan fitur otomatisasi di sistem baru waktu pengerjaan yang sebelumnya memakai waktu 2 hari kini bisa selesai dengan beberapa jam dan dengan tingkat kesalahan data yang lebih rendah.', 'Kendala yang dihadapi yakni tugassehari-hariyang terlalu padat membuang waktu untuk mempraktikkan/menghadapi ilmu baru menjadi terbatas. Dukungan yang diperlukan diberikan fleksibilitas/waktu yangkhusus untuk fokus mengimlentasikan hasil pelatihan.', 'Terbentuknya komunitas belajar antar operator dan guru untuk saling berbagi aplikasi , website, modul ajar, dan berdiskusi mengenai kendala pembelajaran.', NULL, NULL, NULL, 'H. Mawardi', 'SDN 3 Nyerot', 'Kepala Sekolah', 'Eliana Widyastuti,S.E.', 'BGTK Provinsi NTB', '2026-10-27', NULL, NULL, NULL),
(7, 'BK', NULL, 7, '2026-10-27', 'Isman Hadi', 'BK', 'Prita Anugerah', 'Selesai', '{\"instansi_petugas\":\"BGTK NTB\",\"lokasi_monev\":\"SDN 1 Sigar Penjalin\",\"jabatan\":\"BK\",\"satuan_pendidikan\":\"SDN 1 Sigar Penjalin\",\"masa_kerja\":\"3\",\"nama_kegiatan\":\"Tujuh Jurus BK Hebat\",\"tanggal_pengisian\":\"2026-10-27\"}', NULL, '2026-10-28 02:33:58', '2026-10-28 02:33:58', 'Manajemen waktu dan kepadatan jadwal\r\n1. Beban kerja ganda: kesulitan membagi fokus antara menyelesaikan materu pelatihan yang padat dengan kewajiban harian di sekolah (mengajar, mengoreksi dan mengurus administrasi)\r\n2. Durasi eksplorasi materi: beberapa modul (seperti jurus kelola emosi dengan rumus TANYA atau jurus tumbuhkan resiliensi) memerlukan waktu perenungan dan latihan yang cukup lama untuk benar-benar dikuasi secara mendalam.', 'metode pembelajaran yang berpusat pada refleksi:\r\n1. ruang refleksi diri: sesi di mana peserta diminta merefleksikan emosi dan kebiasaan mengajar mereka sendiri terlebih dahulu sebelum menerapkannya ke murid. hal ini memnuat guru merasakan manfaat langsung dari jurus tersebut.\r\n2. studi kasus kontekstual: penggunaan contoh-contoh kasus yang sangat relevan dengan realitas dunia sekolah saat ini, sehingga solusi yang didiskuskan bersifat membumi dan realistis', 'perbanyak sesi simulasi dan pendampingan (coaching): mengurangi porsi pemaparan teori pada pelatihan berikutnya dan menggantinya dengan sesi role play (sumulasi) penanganan kasus secara langsung agar guru lebih percaya diri.', NULL, NULL, NULL, NULL, NULL, 'Isman Hadi', 'SDN 1 Sigar Penjalin', 'BK', 'Prita Anugerah', 'BGTK NTB', '2026-10-27', NULL, NULL, NULL),
(8, 'TENDIK', NULL, 4, '2026-10-27', 'Hendra Asmuni', 'Tendik', 'Eliana Widyastuti,S.E.', 'Selesai', '{\"instansi_petugas\":\"BGTK Provinsi NTB\",\"lokasi_monev\":\"SDN 3 Nyerot\",\"tanggal_pelaksanaan\":\"2026-10-27\",\"jabatan_responden\":\"Tendik\",\"satuan_pendidikan\":\"SDN 3 Nyerot\",\"masa_kerja\":\"19\",\"nama_pelatihan\":\"Tim Monitoring dan Evaluasi Program Prioritas Kepemimpinan sekolah, Implementasi 7 Jurus BK Hebat dan Tes Kompetensi Akademik\"}', NULL, '2026-10-28 02:48:37', '2026-10-28 02:48:37', 'Jadi lebih tahu cara menyelesaikan Administrasi sekolah lebih Praktis dan efisen.', 'Materi Penggunaan aplikasi administrasi baik yang ofline maupun yang online', 'Administrasi kelas memakai online yang bekerja sama dengan guru lain.', 'kendalanya dalam hal penyampain', 'Dampak semua pelaporan lebih cepat dan akurat dalam melayani teman-teman guru di sekolah. saran Sering mengadakan kegiatan dengan level yang lebihatas lagi dari sebelumnya.', NULL, NULL, NULL, 'Hendra Asmuni', 'SDN 3 Nyerot', 'Tendik', 'Eliana Widyastuti,S.E.', 'BGTK Provinsi NTB', '2026-10-27', NULL, NULL, NULL),
(9, 'BCKS', NULL, 9, '2026-10-28', 'NUQRAH, S.Si', 'BCKS', 'Baharudin', 'Selesai', NULL, NULL, '2026-10-28 04:23:56', '2026-10-28 04:23:56', 'Menurut saya RPTKS yang disusun setelah pelatihan BCKS memberikan dampak positif terhadap pengelolaan sekolah, Pelaksanaanya mendorong kolaborasi antar guru, perencanaan program yang lebih terarah, kunci keberhasilannya adalah perencanaan yang matang komunikasi yang baik, kerjasama seluruh warga sekolah.', 'Kendala yang dihadapi: Keterbatasan Anggaran, padatnya jadwal kegiatan sekolah serta perbedaan pemahaman dan kesiapan guru dalam melaksanakan program baru, untuk mengatasinya saya berupaya menentukan skala prioritas, memanfaatkan sumber daya yang tersedia, membangun komunikasi dan koordinasi dengan rekan guru, melaksanakan program secara bertahap.', 'Setelah mengikuti pelatihan BCKS saya merasa lebih memahami pentingnya mengambil keputusan secara objektif, berdasarkan data dan mempertimbangkan kebutuhan warga sekolah, saya juga lebih terbuka terhadap pendapat dan masukan dari berbagai pihak.', 'Dukungan kepala sekolah, rekan guru, dan pengawas sekolah sangat memabntu dalam melaksanakan ide-ide baru disekolah. Kepala sekolah yang merupakan BCKS angkatan Pertama memberikan arahan dan kesempatan untuk berinovasi, rekan guru membantu melalui kolaborasi dan berbagi pengalaman, sedangkan Pengawas sekolah, memberikan pendampingan masukan dan evaluais terhadap program yang dilaksanakan.', 'Saya memastikan keberlanjutan program inovasi dengan menyusun perencanaan yang jelas mendokumentasikan setiap kegiatan dan hasil evaluasi, serta menjadikan program sebagai bagian dari rencana kerja sekolah', 'Nuqrah, S.Si', 'SMA Negeri 1 Palibelo', 'Angkatan 3', 'NUQRAH, S.Si', 'SMA Negeri 1 Palibelo', 'BCKS', 'Baharudin', 'BGTK NTB', '2026-10-28', NULL, NULL, NULL),
